<?php require __DIR__.'/app/bootstrap.php';$p=query('SELECT * FROM products WHERE slug=? AND active=1',[(string)($_GET['slug']??'')])->fetch();if(!$p){http_response_code(404);render_header('Product not found');echo '<main class="page"><h1>Product not found.</h1><a href="'.url().'">Back to the shop</a></main>';render_footer();exit;}$variants=query('SELECT * FROM variants WHERE product_id=? ORDER BY id',[$p['id']])->fetchAll();$available=array_filter($variants,fn($v)=>$v['stock']===null||(int)$v['stock']>0);$gallery=product_gallery($p);render_header($p['name']); ?>
<main class="page"><a class="back-link" href="<?=url('index.php#shop')?>">← ALL CLOTHING</a><div class="product"><div class="gallery"><div class="product-image"><span class="image-label">FLAWED URBANWEAR</span><img id="main-image" src="<?=url(h($p['image']))?>" alt="<?=h($p['name'])?> — view 1"></div><?php if(count($gallery)>1):?><div class="views gallery-views"><?php foreach($gallery as $i=>$photo):?><button type="button" class="<?=$i===0?'active':''?>" data-image="<?=url(h($photo))?>" aria-pressed="<?=$i===0?'true':'false'?>" data-alt="<?=h($p['name'])?> — view <?=$i+1?>"><img src="<?=url(h($photo))?>" alt="View <?=$i+1?>" loading="lazy"></button><?php endforeach ?></div><?php endif ?></div>
<div class="product-details"><p class="eyebrow">FLAWED URBANWEAR / <?=h($p['category']??'CLOTHING')?></p><h1 class="product-title"><?=h($p['name'])?></h1><p class="price"><?=money($p['price'])?> <span>BDT</span></p><?php if(!empty($p['short_description'])):?><p><?=h($p['short_description'])?></p><?php endif ?><p class="stock-status"><?=$available?'AVAILABLE TO ORDER':'SOLD OUT — CURRENTLY UNAVAILABLE'?></p><p class="description"><?=nl2br(h($p['description']))?></p>
<form method="post" action="<?=url('cart.php')?>"><?=csrf_input()?><input type="hidden" name="product_id" value="<?=h($p['id'])?>"><input type="hidden" name="action" value="add"><fieldset><legend>SELECT SIZE</legend><div class="size-options"><?php foreach($variants as $v):?><label class="size-choice"><input type="radio" name="size" value="<?=h($v['size'])?>" required <?= $v['stock']!==null && (int)$v['stock']===0?'disabled':'' ?>><span><?=h($v['size'])?><small><?=$v['stock']===null?'Available':((int)$v['stock']===0?'Sold out':h($v['stock']).' left')?></small></span></label><?php endforeach ?></div></fieldset><?php if($available):?><label class="quantity-label">QUANTITY<input type="number" min="1" max="20" name="quantity" value="1" required></label><button class="button dark" name="destination" value="cart">ADD TO BAG <span>↗</span></button><button class="button outline" name="destination" value="checkout">BUY NOW ↗</button><?php else:?><button class="button dark" type="button" disabled>SOLD OUT</button><?php endif ?></form>
<p class="order-note">Need help with fit? <a href="https://www.instagram.com/flawedurbanwear/" target="_blank" rel="noopener">Ask us on Instagram ↗</a></p><details open><summary>ORDERING & DELIVERY <span>+</span></summary><p>Order online and provide your delivery details at checkout. Your order starts as pending until the team confirms it. Delivery charges are shown at checkout when configured.</p></details><details><summary>PAYMENTS <span>+</span></summary><p>Cash on delivery is available for order requests. bKash online payment is coming later; this site does not collect your bKash PIN or OTP.</p></details></div></div></main><?php render_footer(); ?>
